          "type": "array",
          "items": {"type": "string"}
        },
        "requested_information": {
          "type": "array",
          "items": {"type": "string"}
        }
      }
    },
    "findings": {
      "type": "array",
      "items": {"$ref": "#/$defs/finding"}
    },
    "failure_classes": {
      "type": "array",
      "items": {
        "enum": [
          "missing capability",
          "command discoverability failure",
          "terminology failure",
          "state presentation failure",
          "authority-boundary confusion",
          "evidence presentation failure",
          "unsafe affordance",
          "excessive ceremony",
          "documentation defect",
          "protocol/runtime defect",
          "model-specific operator failure",
          "scenario ambiguity",
          "evaluator contamination"
        ]
      }
    },
    "evidence_citations": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["location", "supports"],
        "properties": {
          "location": {"type": "string", "minLength": 1},
          "supports": {"type": "string", "minLength": 1}
        }
      }
    },
    "severity": {"enum": ["critical", "high", "medium", "low", "none"]},
    "confidence": {"type": "number", "minimum": 0, "maximum": 1},
    "attribution": {
      "enum": [
        "interface",
        "documentation",
        "task_design",
        "model_behavior",
        "unresolved_combination"
      ]
    },
    "authority_and_refusal_understood": {"type": ["boolean", "null"]},
    "safety_relevant_errors": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["description", "evidence", "severity"],
        "properties": {
          "description": {"type": "string", "minLength": 1},
          "evidence": {"type": "string", "minLength": 1},
          "severity": {"enum": ["critical", "high", "medium", "low"]}
        }
      }
    },
    "subjective_feedback": {"type": "string", "minLength": 1}
  },
  "$defs": {
    "cited_finding": {
      "type": "object",
      "additionalProperties": false,
      "required": ["description", "evidence"],
      "properties": {
        "description": {"type": "string", "minLength": 1},
        "evidence": {"type": "string", "minLength": 1}
      }
    },
    "finding": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "description",
        "failure_class",
        "evidence_citations",
        "severity",
        "confidence",
        "attribution"
      ],
      "properties": {
        "description": {"type": "string", "minLength": 1},
        "failure_class": {
          "enum": [
            "missing capability",
            "command discoverability failure",
            "terminology failure",
            "state presentation failure",
            "authority-boundary confusion",
            "evidence presentation failure",
            "unsafe affordance",
            "excessive ceremony",
            "documentation defect",
            "protocol/runtime defect",
            "model-specific operator failure",
            "scenario ambiguity",
            "evaluator contamination"
          ]
        },
        "evidence_citations": {
          "type": "array",
          "minItems": 1,
          "items": {"type": "string", "minLength": 1}
        },
        "severity": {
          "enum": ["critical", "high", "medium", "low"]
        },
        "confidence": {"type": "number", "minimum": 0, "maximum": 1},
        "attribution": {
          "enum": [
            "interface",
            "documentation",
            "task_design",
            "model_behavior",
            "unresolved_combination"
          ]
        }
      }
    },
    "result": {
      "type": "object",
      "additionalProperties": false,
      "required": ["result", "evidence"],
      "properties": {
        "result": {
          "enum": ["yes", "no", "unknown", "not_applicable"]
        },
        "evidence": {"type": "string", "minLength": 1}
      }
    }
  }
}

